// Empty owner: checked read remains in facts, no execution.
export function empty(): f64 {
  const items: f64[] = [];
  const same = items;
  return same[0];
}

// Equal-length index is represented, never folded or trapped here.
export function equal(): f64 {
  const items: f64[] = [1, -0];
  return items[2];
}

// Maximum admitted array index still produces a checked operation.
export function far(): f64 {
  const items: f64[] = [0.1];
  const same: f64[] = items;
  return same[4294967294];
}

export function overwrite(): f64 {
  const a: f64[] = [1.0, 2.0];
  a[1] = 3.0;
  return a[0];
}

// 🧭 dynamic dense aliases é
export function zeta(i: u32, n: u32, value: f64): f64 {
  const original: f64[] = [-0, 0.1];
  const same = original;
  const châin: f64[] = same;
  châin[i] = value;
  same.length = n;
  return original[i];
}

export function alpha(i: u32, value: f64): f64 {
  const original: f64[] = [2.0];
  original[i] = value;
  return original[i];
}

export function appendThenShrink(): f64 {
  const empty: f64[] = [];
  const same = empty;
  same[0] = 1.0;
  empty[1] = same[0];
  same.length = 1;
  return empty[0];
}

export function uncertain(i: u32, n: u32, value: f64): f64 {
  const a: f64[] = [1.0, 2.0];
  const alias = a;
  alias[i] = a[0];
  a[2] = value;
  alias.length = n;
  a.length = 4294967295;
  return a[4294967294];
}

